    private MapAdministrationService requiredMaps(){if(maps==null)throw new Problem(404,"NOT_FOUND","マップ管理は利用できません。");return maps;}private MapProfile importMap(HttpExchange x)throws IOException{Map<String,String> q=query(x);String id=q.getOrDefault("mapId",""),name=q.getOrDefault("displayName","");if(id.isBlank()||name.isBlank())throw new Problem(400,"INVALID_INPUT","mapIdと表示名が必要です。");java.nio.file.Path temp=java.nio.file.Files.createTempFile("orushio-map-",".zip");try{try(var out=java.nio.file.Files.newOutputStream(temp)){byte[] b=new byte[8192];long total=0;for(int n;(n=x.getRequestBody().read(b))>=0;){total+=n;if(total>SafeWorldZipImporter.DEFAULT_LIMITS.maxZipBytes())throw new Problem(413,"ZIP_SIZE","ZIPサイズが上限を超えています。");out.write(b,0,n);}}return requiredMaps().importZip(temp,id,name);}finally{java.nio.file.Files.deleteIfExists(temp);}}private static Map<String,String> query(HttpExchange x){Map<String,String> result=new HashMap<>();String raw=x.getRequestURI().getRawQuery();if(raw==null)return result;for(String part:raw.split("&")){String[] pair=part.split("=",2);if(pair.length==2)result.put(java.net.URLDecoder.decode(pair[0],StandardCharsets.UTF_8),java.net.URLDecoder.decode(pair[1],StandardCharsets.UTF_8));}return result;}private static Map<String,Object> mapView(MapProfile p){Map<String,Object> v=new LinkedHashMap<>();v.put("mapId",p.mapId().value());v.put("displayName",p.displayName());v.put("enabled",p.enabled());v.put("setupComplete",p.setupComplete());v.put("missing",p.missingRequirements().stream().map(MapFieldCatalog::label).toList());v.put("createdAt",p.createdAt().toString());return v;}private static Map<String,Object> setupView(MapAdministrationService.SetupView s){List<Map<String,Object>> fields=MapFieldCatalog.FIELDS.stream().map(field->{int count=s.counts().getOrDefault(field.key(),0);List<Map<String,Object>> entries=s.entries().getOrDefault(field.key(),List.of()).stream().map(entry->entry.point()!=null?pointView(entry.point()):regionView(entry.region())).toList();Map<String,Object> view=new LinkedHashMap<>();view.put("key",field.key());view.put("label",field.label());view.put("area",field.area());view.put("required",field.required());view.put("requiredCount",field.requiredCount());view.put("count",count);view.put("complete",!field.required()||count>=field.requiredCount());view.put("entries",entries);return view;}).toList();List<Map<String,Object>> markerAreas=s.markerAreas().stream().map(area->Map.<String,Object>of("areaId",area.areaId(),"label",area.label(),"markerCount",area.markerCount(),"markers",area.markers().stream().map(AdminHttpServer::markerView).toList())).toList();Map<String,Object> result=new LinkedHashMap<>();result.put("active",s.active());result.put("mapId",s.mapId());result.put("displayName",s.displayName());result.put("administrator",s.administrator());result.put("selectedField",s.selectedField());result.put("area",s.area());result.put("missing",s.missing().stream().map(MapFieldCatalog::label).toList());result.put("fields",fields);result.put("markerAreas",markerAreas);result.put("revision",s.revision());return result;}private static Map<String,Object> markerView(SpawnMarker marker){Map<String,Object> value=new LinkedHashMap<>(pointView(marker.position()));value.put("markerId",marker.markerId().toString());value.put("areaId",marker.areaId());value.put("enabled",marker.enabled());return value;}private static Map<String,Object> pointView(BlockPoint p){return Map.of("x",p.x(),"y",p.y(),"z",p.z(),"yaw",p.yaw(),"pitch",p.pitch());}private static Map<String,Object> regionView(Cuboid c){return Map.of("minX",c.minX(),"minY",c.minY(),"minZ",c.minZ(),"maxX",c.maxX(),"maxY",c.maxY(),"maxZ",c.maxZ());}
    private void loggedError(HttpExchange x,String trace,int status,String code,String message,String operation)throws IOException{audit.record(trace,"HTTP_ERROR",code,operation);error(x,status,code,message,trace);}private static String required(HttpExchange x,String name){String v=header(x,name);if(v.isBlank())throw new Problem(400,"INVALID_INPUT",name+"が必要です。");return v;}private static String clientKey(HttpExchange x){return x.getRemoteAddress().getAddress().getHostAddress();}private static String header(HttpExchange x,String n){String v=x.getRequestHeaders().getFirst(n);return v==null?"":v;}private static boolean method(HttpExchange x,String m){return x.getRequestMethod().equals(m);}
    private static void enforceMethod(String path,String method){Set<String> allowed=API_METHODS.get(path);if(allowed!=null&&!allowed.contains(method))throw new Problem(405,"METHOD_NOT_ALLOWED","このHTTPメソッドは利用できません。");}
    private void asset(HttpExchange x,String path)throws IOException{String r=switch(path){case "/","/index.html"->"/web/index.html";case "/app.js"->"/web/app.js";case "/style.css"->"/web/style.css";default->null;};if(r==null)throw new Problem(404,"NOT_FOUND","ページがありません。");try(var in=getClass().getResourceAsStream(r)){if(in==null)throw new Problem(404,"NOT_FOUND","ページがありません。");byte[] b=in.readAllBytes();x.getResponseHeaders().set("Content-Type",r.endsWith(".html")?"text/html; charset=utf-8":r.endsWith(".css")?"text/css; charset=utf-8":"text/javascript; charset=utf-8");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);}}
    private static void ok(HttpExchange x,Object d)throws IOException{send(x,200,Json.value(Map.of("ok",true,"data",d)));}private static void error(HttpExchange x,int s,String c,String m,String t)throws IOException{send(x,s,Json.value(Map.of("ok",false,"error",Map.of("code",c,"message",m,"fields",Map.of(),"traceId",t))));}private static void send(HttpExchange x,int s,String body)throws IOException{byte[] b=body.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(s,b.length);x.getResponseBody().write(b);}private static void addHeaders(HttpExchange x){x.getResponseHeaders().set("X-Content-Type-Options","nosniff");x.getResponseHeaders().set("Content-Security-Policy","default-src 'self'; connect-src 'self'; script-src 'self'; style-src 'self'");x.getResponseHeaders().set("Cache-Control","no-store");}
